package com.narudzbine.inventory.application;
import com.narudzbine.inventory.api.*;
import com.narudzbine.inventory.api.InventoryReconciliation.*;
import com.narudzbine.inventory.api.VendorInventory.Tracking;
import com.narudzbine.audit.api.InventoryAudit;
import com.narudzbine.shared.api.UuidGenerator;
import java.sql.Timestamp;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.json.JsonMapper;
@Service
@Transactional(propagation=Propagation.MANDATORY)
public class JdbcInventoryReconciliation implements InventoryReconciliation {
 private static final JsonMapper JSON=JsonMapper.builder().build();
 private final JdbcTemplate jdbc;private final VendorInventory inventory;private final InventoryAudit audit;private final Clock clock;private final UuidGenerator ids;
 public JdbcInventoryReconciliation(JdbcTemplate jdbc,VendorInventory inventory,InventoryAudit audit,Clock clock,UuidGenerator ids){this.jdbc=jdbc;this.inventory=inventory;this.audit=audit;this.clock=clock;this.ids=ids;}
 public Preview prepare(UUID actor,UUID vendor){guard(vendor);var control=inventory.tracking(vendor);if(control.enabled()){throw fail(InventoryFailure.Reason.TRACKING_ENABLED);}UUID id=ids.next();long count=jdbc.queryForObject("SELECT count(*) FROM stock_balance WHERE vendor_id=?",Long.class,vendor);jdbc.update("INSERT INTO inventory_preview(id,vendor_id,source_generation,source_epoch,expires_at,product_count) VALUES (?,?,?,?,?,?)",id,vendor,control.generation(),control.epoch(),time(now().plusSeconds(86400)),count);jdbc.update("INSERT INTO inventory_preview_line(preview_id,product_id,source_revision,source_count,source_credit,available_count) SELECT ?,product_id,revision,available_count,credit_quantity,COALESCE(available_count,0) FROM stock_balance WHERE vendor_id=? ORDER BY product_id",id,vendor);jdbc.update("UPDATE inventory_preview SET sealed=true WHERE id=?",id);audit.reconciliation(actor,id,"PREPARED");return get(vendor,id);}
 public Preview get(UUID vendor,UUID id){var rows=jdbc.query("SELECT p.*,(SELECT count(*) FROM inventory_preview_line l WHERE l.preview_id=p.id AND l.acknowledged) AS confirmed_count FROM inventory_preview p WHERE p.id=? AND p.vendor_id=? AND p.sealed",(r,n)->new Preview(r.getObject("id",UUID.class),vendor,r.getLong("revision"),r.getLong("source_generation"),r.getLong("source_epoch"),r.getTimestamp("expires_at").toInstant(),r.getLong("product_count"),r.getLong("confirmed_count"),r.getBoolean("applied")),id,vendor);if(rows.isEmpty()){throw fail(InventoryFailure.Reason.NOT_FOUND);}var p=rows.getFirst();if(!now().isBefore(p.expiresAt())){throw fail(InventoryFailure.Reason.PREVIEW_EXPIRED);}if(!p.applied()){var c=inventory.tracking(vendor);if(c.enabled()||c.generation()!=p.generation()||c.epoch()!=p.epoch()){throw fail(InventoryFailure.Reason.PREVIEW_STALE);}}return p;}
 public Line line(UUID vendor,UUID id,UUID product){var p=get(vendor,id);var rows=jdbc.query("SELECT * FROM inventory_preview_line WHERE preview_id=? AND product_id=?",(r,n)->map(r,p.epoch()),id,product);if(rows.isEmpty()){throw fail(InventoryFailure.Reason.NOT_FOUND);}return rows.getFirst();}
 public Lines lines(UUID vendor,UUID id,int size,UUID after){var p=get(vendor,id);var rows=jdbc.query("SELECT * FROM inventory_preview_line WHERE preview_id=? AND (?::uuid IS NULL OR product_id>?) ORDER BY product_id LIMIT ?",(r,n)->map(r,p.epoch()),id,after,after,size+1);return new Lines(rows.stream().limit(size).toList(),rows.size()>size);}
 public Preview acknowledge(UUID actor,UUID vendor,UUID id,List<Candidate> candidates){guard(vendor);var p=working(vendor,id);if(candidates.isEmpty()||candidates.size()>100||candidates.stream().map(Candidate::productId).distinct().count()!=candidates.size()){throw new IllegalArgumentException("Invalid reconciliation batch");}boolean changed=false;for(var candidate:candidates){var line=line(vendor,id,candidate.productId());if(candidate.sourceRevision()!=line.sourceRevision()){throw fail(InventoryFailure.Reason.PREVIEW_STALE);}if(candidate.availableCount()<0||candidate.availableCount()>1000000000L-line.creditQuantity()){throw new InventoryFailure(InventoryFailure.Reason.INVALID_COUNT,"/lines");}if(!line.acknowledged()||line.availableCount()!=candidate.availableCount()){jdbc.update("UPDATE inventory_preview_line SET available_count=?,acknowledged=true WHERE preview_id=? AND product_id=?",candidate.availableCount(),id,candidate.productId());changed=true;}}if(changed){jdbc.update("UPDATE inventory_preview SET revision=revision+1 WHERE id=?",p.id());audit.reconciliation(actor,id,"ACKNOWLEDGED");}return get(vendor,id);}
 public Tracking enable(UUID actor,UUID vendor,UUID id){guard(vendor);var p=working(vendor,id);if(p.confirmedCount()!=p.productCount()){throw fail(InventoryFailure.Reason.REVIEW_INCOMPLETE);}jdbc.queryForList("SELECT id FROM catalogue_product_identity WHERE id IN (SELECT product_id FROM stock_balance WHERE vendor_id=?) ORDER BY id FOR UPDATE",UUID.class,vendor);jdbc.queryForList("SELECT product_id FROM stock_balance WHERE vendor_id=? ORDER BY product_id FOR UPDATE",UUID.class,vendor);Long differences=jdbc.queryForObject("SELECT count(*) FROM (SELECT * FROM inventory_preview_line WHERE preview_id=?) l FULL JOIN (SELECT * FROM stock_balance WHERE vendor_id=?) b ON b.product_id=l.product_id WHERE l.product_id IS NULL OR b.product_id IS NULL OR l.source_revision<>b.revision OR l.source_count IS DISTINCT FROM b.available_count OR l.source_credit<>b.credit_quantity OR l.available_count::bigint+b.credit_quantity>1000000000",Long.class,id,vendor);if(differences!=0){throw fail(InventoryFailure.Reason.PREVIEW_STALE);}var all=jdbc.query("SELECT * FROM inventory_preview_line WHERE preview_id=? ORDER BY product_id",(r,n)->map(r,p.epoch()),id);jdbc.update("UPDATE inventory_control SET enabled=true,confirmation_epoch=confirmation_epoch+1,revision=revision+1,generation=generation+1 WHERE vendor_id=?",vendor);for(var line:all){var item=inventory.get(vendor,line.productId());if(Objects.equals(item.availableCount(),line.availableCount())){inventory.confirm(actor,vendor,line.productId());}else{inventory.set(actor,vendor,line.productId(),line.availableCount(),null);}}jdbc.update("UPDATE inventory_preview SET applied=true,revision=revision+1 WHERE id=?",id);audit.tracking(actor,vendor,true);audit.reconciliation(actor,id,"APPLIED");return inventory.tracking(vendor);}
 public Tracking disable(UUID actor,UUID vendor){guard(vendor);var old=inventory.tracking(vendor);if(!old.enabled()){return old;}jdbc.update("UPDATE inventory_control SET enabled=false,confirmation_epoch=confirmation_epoch+1,revision=revision+1,generation=generation+1 WHERE vendor_id=?",vendor);audit.tracking(actor,vendor,false);return inventory.tracking(vendor);}
 public Optional<Receipt> replay(UUID actor,UUID vendor,String operation,byte[] identity){var rows=jdbc.queryForList("SELECT * FROM inventory_lifecycle_replay WHERE actor_id=? AND operation=? AND identity_hash=?",actor,operation,identity);if(rows.isEmpty()){return Optional.empty();}var row=rows.getFirst();if(!vendor.equals(row.get("vendor_id"))){throw fail(InventoryFailure.Reason.NOT_FOUND);}if(!now().isBefore(((Timestamp)row.get("expires_at")).toInstant())){throw fail(InventoryFailure.Reason.REPLAY_EXPIRED);}return Optional.of(JSON.readValue(row.get("original_result").toString(),Receipt.class));}
 public void remember(UUID actor,UUID vendor,String operation,byte[] identity,Receipt result){jdbc.update("INSERT INTO inventory_lifecycle_replay(actor_id,vendor_id,operation,identity_hash,original_result,expires_at) VALUES (?,?,?,?,?::jsonb,?)",actor,vendor,operation,identity,JSON.writeValueAsString(result),time(now().plus(7,ChronoUnit.DAYS)));}
 public void compactExpiredReplay(){jdbc.update("WITH expired AS (SELECT actor_id,operation,identity_hash FROM inventory_lifecycle_replay WHERE original_result IS NOT NULL AND expires_at<=? ORDER BY expires_at,actor_id,operation,identity_hash LIMIT 1000 FOR UPDATE SKIP LOCKED) UPDATE inventory_lifecycle_replay p SET original_result=NULL FROM expired e WHERE p.actor_id=e.actor_id AND p.operation=e.operation AND p.identity_hash=e.identity_hash",time(now()));}
 private Preview working(UUID vendor,UUID id){var p=get(vendor,id);if(p.applied()){throw fail(InventoryFailure.Reason.PREVIEW_APPLIED);}return p;}
 private static Line map(java.sql.ResultSet r,long epoch)throws java.sql.SQLException{return new Line(r.getObject("product_id",UUID.class),r.getLong("source_revision"),epoch,r.getInt("available_count"),r.getLong("source_credit"),r.getBoolean("acknowledged"));}
 private void guard(UUID vendor){jdbc.queryForList("SELECT id FROM organization WHERE id=? FOR UPDATE",UUID.class,vendor);jdbc.queryForList("SELECT vendor_id FROM inventory_control WHERE vendor_id=? FOR UPDATE",UUID.class,vendor);}
 private Instant now(){return clock.instant().truncatedTo(ChronoUnit.MILLIS);}
 private static Timestamp time(Instant at){return Timestamp.from(at);}
 private static InventoryFailure fail(InventoryFailure.Reason reason){return new InventoryFailure(reason,null);}
}
